DECLARE @t TABLE (id int, grp int, name nvarchar(10));
INSERT @t VALUES (1, 1, N'a'), (2, 1, N'b&'), (3, 2, N'c'), (4, 2, NULL);
SELECT grp, STUFF((SELECT N', ' + name FROM @t i WHERE i.grp = o.grp ORDER BY id DESC FOR XML PATH('')), 1, 2, N'') AS names FROM @t o GROUP BY grp ORDER BY grp

DECLARE @t TABLE (id int, grp int, name nvarchar(10));
INSERT @t VALUES (1, 1, N'a'), (2, 1, N'b&'), (3, 2, N'c'), (4, 2, NULL);
SELECT o.grp, (SELECT i.name AS [text()] FROM @t i WHERE i.grp = o.grp ORDER BY i.id FOR XML PATH('n'), TYPE) AS names FROM (SELECT DISTINCT grp FROM @t) o ORDER BY o.grp

DECLARE @t TABLE (id int, grp int, name nvarchar(10));
